import numpy as np

def quadratic(x: np.ndarray) -> float:
    target = np.array([1.5, -0.5])
    return 0.5 * np.sum((x - target) ** 2)

def quadratic_grad(x: np.ndarray) -> np.ndarray:
    target = np.array([1.5, -0.5])
    return x - target

x = np.array([-2.0, 2.0])
history = []
for _ in range(60):
    history.append(quadratic(x))
    x = x - 0.15 * quadratic_grad(x)
assert history[-1] < history[0]

"""Small optimization formulation contracts for Chapter 8."""
from __future__ import annotations

from typing import Iterable, Mapping

import numpy as np


class OptimizationFormulationError(ValueError):
    pass


def _vector(name: str, x: Iterable[float]) -> np.ndarray:
    a = np.asarray(x, dtype=float).reshape(-1)
    if a.size == 0 or not np.all(np.isfinite(a)):
        raise OptimizationFormulationError(f"{name} must be non-empty and finite")
    return a


def weighted_objective(terms: Mapping[str, float], scales: Mapping[str, float],
                       weights: Mapping[str, float]) -> dict:
    if set(terms) != set(scales) or set(terms) != set(weights) or not terms:
        raise OptimizationFormulationError("terms, scales, and weights must have equal non-empty keys")
    contributions = {}
    for name, value in terms.items():
        scale = float(scales[name])
        weight = float(weights[name])
        if not np.isfinite(value) or not np.isfinite(scale) or not np.isfinite(weight) or scale <= 0.0 or weight < 0.0:
            raise OptimizationFormulationError("term values must be finite; scales positive; weights non-negative")
        contributions[name] = weight * (float(value) / scale) ** 2
    return {"total": float(sum(contributions.values())), "contributions": contributions}


def least_squares_report(A: Iterable[Iterable[float]], b: Iterable[float], x: Iterable[float]) -> dict:
    matrix = np.asarray(A, dtype=float)
    target = _vector("b", b)
    estimate = _vector("x", x)
    if matrix.ndim != 2 or matrix.shape[0] != target.size or matrix.shape[1] != estimate.size or not np.all(np.isfinite(matrix)):
        raise OptimizationFormulationError("A, b, and x shapes must be compatible and finite")
    residual = matrix @ estimate - target
    gradient = matrix.T @ residual
    return {"residual_norm": float(np.linalg.norm(residual)),
            "gradient_norm": float(np.linalg.norm(gradient)),
            "rank": int(np.linalg.matrix_rank(matrix)),
            "n_observations": int(matrix.shape[0])}


def project_box(x: Iterable[float], lower: Iterable[float], upper: Iterable[float]) -> tuple[np.ndarray, np.ndarray]:
    value, lo, hi = _vector("x", x), _vector("lower", lower), _vector("upper", upper)
    if value.shape != lo.shape or value.shape != hi.shape or np.any(lo > hi):
        raise OptimizationFormulationError("box bounds must match x and satisfy lower <= upper")
    projected = np.clip(value, lo, hi)
    return projected, projected - value


def formulation_gate(objective: float, task_metric: float, feasible: bool,
                     objective_limit: float, task_limit: float) -> dict:
    vals = _vector("gate values", [objective, task_metric, objective_limit, task_limit])
    if objective < 0 or task_metric < 0 or objective_limit < 0 or task_limit < 0:
        raise OptimizationFormulationError("gate values must be non-negative")
    reasons = []
    if not feasible:
        reasons.append("constraint")
    if objective > objective_limit:
        reasons.append("objective")
    if task_metric > task_limit:
        reasons.append("task")
    return {"accepted": not reasons, "reasons": tuple(reasons)}

import numpy as np
import pytest

from optimization_formulation_lab import (
    OptimizationFormulationError,
    formulation_gate,
    least_squares_report,
    project_box,
    weighted_objective,
)


def test_objective_report_exposes_units_as_scales():
    report = weighted_objective({"pose": 0.01, "time": 2.0}, {"pose": 0.01, "time": 1.0}, {"pose": 1.0, "time": 0.5})
    assert report["total"] == pytest.approx(3.0)
    assert set(report["contributions"]) == {"pose", "time"}


def test_least_squares_report_and_box_projection():
    report = least_squares_report([[1, 0], [0, 1]], [1, 2], [1, 2])
    assert report["residual_norm"] == pytest.approx(0.0)
    projected, delta = project_box([2, -1], [0, 0], [1, 1])
    assert np.allclose(projected, [1, 0]) and np.allclose(delta, [-1, 1])


def test_gate_preserves_all_reasons_and_rejects_bad_bounds():
    assert formulation_gate(2, 3, False, 1, 1) == {"accepted": False, "reasons": ("constraint", "objective", "task")}
    with pytest.raises(OptimizationFormulationError):
        project_box([0], [2], [1])
